import { sha256 } from './hash';

/**
 * Report branding (Pro, SPEC §9.3): the organisation's name, logo, colour and
 * protective marking on the export report. It changes how the report looks,
 * never what it says about the evidence: the integrity sections and the
 * "Generated by EviCap" footer stay as they are.
 *
 * Stored in chrome.storage.local under "branding", apart from the settings,
 * so the logo isn't copied into every settings.changed audit event.
 */
export interface Branding {
  /** Shown on the report cover as "Prepared by …". */
  organisation: string;
  /** A PNG data: URL, already resized by `prepareLogo`. */
  logoDataUrl: string | null;
  /** Headings and rules, as #rrggbb. Null for EviCap's blue. */
  accent: string | null;
  /** A protective marking such as OFFICIAL-SENSITIVE, at the top and bottom of every PDF page. */
  marking: string;
}

export const EMPTY_BRANDING: Branding = { organisation: '', logoDataUrl: null, accent: null, marking: '' };
export const DEFAULT_ACCENT = '#006d77'; // EviCap's Security Teal (src/lib/brand.ts)
export const BRANDING_LIMITS = { organisation: 120, marking: 60, logoChars: 400_000, logoWidth: 900, logoHeight: 300 };
/** Headings in the accent colour must stay readable on white paper (WCAG AA for normal text). */
export const MIN_ACCENT_CONTRAST = 4.5;

const HEX = /^#[0-9a-f]{6}$/;
const PNG_DATA_URL = /^data:image\/png;base64,[A-Za-z0-9+/]+={0,2}$/;

/** WCAG contrast ratio between two #rrggbb colours. */
export function contrastRatio(a: string, b = '#ffffff'): number {
  const lum = (hex: string) => {
    const [r, g, bl] = [1, 3, 5].map((i) => {
      const v = parseInt(hex.slice(i, i + 2), 16) / 255;
      return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
    });
    return 0.2126 * r! + 0.7152 * g! + 0.0722 * bl!;
  };
  const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
  return (x! + 0.05) / (y! + 0.05);
}

const oneLine = (v: unknown, max: number) =>
  String(v ?? '')
    .replace(/[\u0000-\u001f\u007f]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);

/** Check and tidy branding from the settings form. Throws an Error with a message for the user. */
export function cleanBranding(input: Partial<Branding> | null | undefined): Branding {
  const b = input ?? {};
  const organisation = oneLine(b.organisation, BRANDING_LIMITS.organisation);
  const marking = oneLine(b.marking, BRANDING_LIMITS.marking);
  let accent: string | null = b.accent ? String(b.accent).trim().toLowerCase() : null;
  if (accent === DEFAULT_ACCENT) accent = null;
  if (accent !== null) {
    if (!HEX.test(accent)) throw new Error('The colour must be written as #rrggbb, for example #0b5d3b.');
    if (contrastRatio(accent) < MIN_ACCENT_CONTRAST) {
      throw new Error('That colour is too light to read on white paper. Choose a darker shade.');
    }
  }
  const logoDataUrl = b.logoDataUrl ?? null;
  if (logoDataUrl !== null) {
    if (!PNG_DATA_URL.test(logoDataUrl)) throw new Error('The logo must be a PNG image prepared by EviCap.');
    if (logoDataUrl.length > BRANDING_LIMITS.logoChars) throw new Error('The logo is too large. Use a smaller or simpler image.');
  }
  return { organisation, logoDataUrl, accent, marking };
}

export function isBranded(b: Branding | null | undefined): b is Branding {
  return !!b && !!(b.organisation || b.logoDataUrl || b.accent || b.marking);
}

/** What the audit log records: the logo by its hash, not the image. */
export async function brandingSummary(b: Branding) {
  return {
    organisation: b.organisation || null,
    logo: b.logoDataUrl ? await sha256(b.logoDataUrl) : null,
    accent: b.accent,
    marking: b.marking || null,
  };
}

const KEY = 'branding';

export async function getBranding(): Promise<Branding> {
  const v = (await chrome.storage.local.get(KEY))[KEY] as Partial<Branding> | undefined;
  try {
    return cleanBranding({ ...EMPTY_BRANDING, ...(v ?? {}) });
  } catch {
    return EMPTY_BRANDING;
  }
}

export async function setBranding(b: Branding): Promise<Branding> {
  await chrome.storage.local.set({ [KEY]: b });
  return b;
}

/**
 * Turn an uploaded image into a PNG data: URL no larger than 900 × 300 px.
 * Re-drawing it drops anything but the pixels (metadata, scripts in SVG).
 * Runs in the dashboard.
 */
export async function prepareLogo(file: Blob): Promise<string> {
  if (!/^image\/(png|jpeg|webp|gif)$/.test(file.type)) throw new Error('Choose a PNG, JPEG, WebP or GIF image.');
  if (file.size > 10 * 1024 * 1024) throw new Error('That image is over 10 MB. Choose a smaller file.');
  let bmp: ImageBitmap;
  try {
    bmp = await createImageBitmap(file);
  } catch {
    throw new Error('That file could not be read as an image.');
  }
  const scale = Math.min(1, BRANDING_LIMITS.logoWidth / bmp.width, BRANDING_LIMITS.logoHeight / bmp.height);
  const w = Math.max(1, Math.round(bmp.width * scale));
  const h = Math.max(1, Math.round(bmp.height * scale));
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Could not prepare the logo.');
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(bmp, 0, 0, w, h);
  bmp.close();
  const url = canvas.toDataURL('image/png');
  if (url.length > BRANDING_LIMITS.logoChars) throw new Error('The logo is too detailed to store. Use a simpler or smaller image.');
  return url;
}
